scope_code:
.thumb-glyph--star::before {
  content: "";
  position: absolute;
  left: 32%;
  bottom: -10px;
  width: 14px;
  height: 12px;
  background: #ff9f43;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  opacity: 0.9;
}

