.thumb-glyph--star {
  position: relative;
  left: 34%;
  bottom: 26%;
  width: 38px;
  height: 42px;
  background: linear-gradient(180deg, var(--accent), #2a9fd4);
  clip-path: polygon(50% 0, 100% 62%, 74% 62%, 74% 100%, 26% 100%, 26% 62%, 0 62%);
  box-shadow: 0 0 24px rgba(76, 201, 240, 0.6);
}

